def _usage(
    provider: str,
    controls: dict[str, object] | None = None,
) -> list[dict[str, object]]:
    record: dict[str, object] = {
        "provider": provider,
        "usage_source": "provider_response",
    }
    if controls is not None:
        record["requested_controls"] = controls
        record["forwarded_controls"] = controls
    return [record]


